// Initialize multi-account pool if not exists
if (!flow.get("accountPool")) {
    flow.set("accountPool", [
        { email: "account1@gmail.com", apiKey: "AIzaSy_YOUR_KEY_1_HERE" },
        { email: "account2@gmail.com", apiKey: "AIzaSy_YOUR_KEY_2_HERE" },
        { email: "account3@gmail.com", apiKey: "AIzaSy_YOUR_KEY_3_HERE" }
    ]);
    flow.set("currentAccountIndex", 0);
}

let pool = flow.get("accountPool");
let index = flow.get("currentAccountIndex");

let currentAccount = pool[index];
msg.currentAccount = currentAccount;
msg.retryCount = msg.retryCount || 0;

node.warn(`Using account: ${currentAccount.email} (Index: ${index})`);
return msg;

let response = msg.payload;
if (response && response.candidates && response.candidates[0]) {
    let text = response.candidates[0].content.parts[0].text;
    msg.payload = {
        topic: text,
        prompt: `Write an engaging 60-second video script and social media caption for YouTube Shorts, Facebook Reels, and TikTok based on this topic: ${text}`
    };
    return msg;
}
node.error("Failed to generate ideation", msg);
return null;

let response = msg.payload;
if (response && response.candidates && response.candidates[0]) {
    let scriptText = response.candidates[0].content.parts[0].text;
    msg.content = {
        script: scriptText,
        title: "Mind Blowing Fact of the Day! 🤯 #shorts",
        platforms: ["youtube", "facebook", "tiktok"]
    };
    // Output 1: YouTube, Output 2: Facebook, Output 3: TikTok, Output 4: Drive Archival
    return [msg, msg, msg, msg]; 
}
return null;

// Prepare timestamped filename
let now = new Date();
let filename = `ContentArchive_${now.toISOString().replace(/[:.]/g, '-')}.json`;

// Package all metadata
let archivalData = {
    timestamp: now.toISOString(),
    topic: msg.payload.topic,
    script: msg.content.script,
    title: msg.content.title,
    platforms: msg.content.platforms
};

msg.filename = filename;
msg.payload = archivalData;

// Drive OAuth Config (Replace with your separate account details)
msg.driveConfig = {
    clientId: "YOUR_DRIVE_CLIENT_ID",
    clientSecret: "YOUR_DRIVE_CLIENT_SECRET",
    refreshToken: "YOUR_DRIVE_REFRESH_TOKEN"
};

return msg;

if (msg.payload && msg.payload.access_token) {
    let token = msg.payload.access_token;
    let filename = msg.filename;
    let content = JSON.stringify(msg.payload, null, 2);

    msg.headers = {
        "Authorization": "Bearer " + token,
        "Content-Type": "application/json"
    };

    // Simple upload metadata
    msg.url = "https://www.googleapis.com/upload/drive/v3/files?uploadType=media";
    msg.payload = content;

    return msg;
}
node.error("Failed to refresh Drive token", msg);
return null;

let err = msg.error;
let pool = flow.get("accountPool");
let index = flow.get("currentAccountIndex");

node.warn(`Quota / Error encountered on account ${pool[index].email}: ${err.message}. Rotating account...`);

// Rotate to next account in round-robin fashion
index = (index + 1) % pool.length;
flow.set("currentAccountIndex", index);

msg.retryCount = (msg.retryCount || 0) + 1;

if (msg.retryCount <= pool.length) {
    // Retry with new account
    return [msg];
} else {
    node.error("All accounts in pool exhausted quota!");
    return null;
}
